package com.keyforge.nativeload;
import java.sql.*;import java.util.*;
/** Reads every Identity source page, upserts edges, and sweeps only after a confirmed successful full scan. */
public final class NativeWorkgroupMembershipImportService {private final NativeWorkgroupMembershipClient client;private final NativeWorkgroupMembershipRepository repo;private final int pageSize;public NativeWorkgroupMembershipImportService(NativeWorkgroupMembershipClient c,NativeWorkgroupMembershipRepository r,int p){client=c;repo=r;pageSize=p>0?p:100;}public Result run(Connection conn)throws SQLException{repo.ensure(conn);NativeWorkgroupMembershipParser parser=new NativeWorkgroupMembershipParser();Set<String>keep=new LinkedHashSet<>();int start=0,scanned=0,inserted=0,updated=0,failed=0;while(true){NativeWorkgroupMembershipPage page=parser.parse(client.fetch(start,pageSize));for(NativeWorkgroupMembershipRecord r:page.rows){scanned++;try{String id=NativeWorkgroupMembershipRepository.edgeId(r);keep.add(id);if(repo.upsert(conn,r)==NativeWorkgroupMembershipRepository.Outcome.INSERTED)inserted++;else updated++;}catch(RuntimeException|SQLException e){failed++;System.err.println("Native workgroup membership failed (workgroup="+r.workgroupId+", identity="+r.identityId+"): "+e.getMessage());}}if(page.done){boolean skip=keep.isEmpty()||failed>0;int deleted=skip?0:repo.sweep(conn,keep);return new Result(scanned,keep.size(),inserted,updated,failed,deleted,skip);}if(page.nextStart<=start)throw new NativeImportException("Membership pagination did not advance (start="+start+")");start=page.nextStart;}}public static final class Result{public final int edges,distinct,inserted,updated,failed,deleted;public final boolean sweepSkipped;Result(int e,int d,int i,int u,int f,int x,boolean s){edges=e;distinct=d;inserted=i;updated=u;failed=f;deleted=x;sweepSkipped=s;}}}
